import { AfterViewInit, Component, ElementRef, Host, Inject, Input, SkipSelf, forwardRef } from '@angular/core';
import { AbstractControl, ControlContainer, UntypedFormGroup } from '@angular/forms';
import { MessageModule } from 'espd-common/i18n';

@Component({
	selector: 'espd-countdown',
	templateUrl: 'countdown.component.html',
	imports: [
		MessageModule
	],
	styleUrls: ['countdown.component.scss']
})
export class CountdownComponent implements AfterViewInit {
	@Input() public maxLength?: number = 0;

	@Input()
	public control?: AbstractControl;
	private parent: ControlContainer;

	constructor(private element: ElementRef, @Inject(forwardRef(() => ControlContainer)) @Host() @SkipSelf() parent: ControlContainer) {
		this.parent = parent;
	}

	public ngAfterViewInit(): void {
		if (!this.control) {
			setTimeout(() => {
				const input = this.element.nativeElement.querySelector('input') || this.element.nativeElement.querySelector('textarea');

				if (!input) {
					throw new Error('Countdown directive must wrap a textarea or input.');
				}

				const formControlName = input.getAttribute('formControlName');
				if (!formControlName) {
					throw new Error('Countdown directive must wrap an input bound to a form control.');
				}

				this.control = (this.parent.control as UntypedFormGroup).controls[formControlName];
			});
		}
	}
}